std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(
        boost::irange<std::size_t>(0, cols_).begin(),
        boost::irange<std::size_t>(0, cols_).end(),
        result.begin(),
        [this](std::size_t c) {
            return std::accumulate(
                boost::irange<std::size_t>(0, rows_).begin(),
                boost::irange<std::size_t>(0, rows_).end(),
                0.0,
                [this, c](double s, std::size_t r) { return s + at(r, c); });
        });
    return result;
}

