std::vector<double> Matrix::SumPerColumn() const {
    struct StrideIterator {
        using iterator_category = std::input_iterator_tag;
        using value_type = double;
        using difference_type = std::ptrdiff_t;
        using pointer = const double*;
        using reference = double;
        const double* p;
        std::size_t stride;
        reference operator*() const { return *p; }
        StrideIterator& operator++() { p += stride; return *this; }
        StrideIterator operator++(int) { auto t = *this; ++*this; return t; }
        bool operator!=(const StrideIterator& o) const { return p != o.p; }
    };
    std::vector<std::size_t> indices(cols_);
    std::iota(indices.begin(), indices.end(), std::size_t{0});
    std::vector<double> result(cols_);
    std::transform(indices.begin(), indices.end(), result.begin(),
        [this](std::size_t c) {
            return std::accumulate(
                StrideIterator{&at(0, c), cols_},
                StrideIterator{&at(rows_, c), cols_},
                0.0);
        });
    return result;
}

